pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll find owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Search for numConfirmationsRequired in storage slots
        // It's likely a small integer (2, 3, etc.)
        uint256 foundSlot = type(uint256).max;

        // Search first 100 slots (reasonable for a simple contract)
        for (uint256 i = 0; i < 100; i++) {
            bytes32 slotValue = vm.load(TARGET, bytes32(i));
            uint256 value = uint256(slotValue);

            // Look for small values that could be numConfirmationsRequired (2-10)
            if (value >= 2 && value <= 10) {
                foundSlot = i;
                console.log("Found potential numConfirmationsRequired at slot", i, "value:", value);

                // Overwrite with 1
                vm.store(TARGET, bytes32(i), bytes32(uint256(1)));

                // Verify the change
                bytes32 newValue = vm.load(TARGET, bytes32(i));
                console.log("New value at slot", i, ":", uint256(newValue));

                // Check if it's now less than 2
                assertLt(uint256(newValue), 2, "numConfirmationsRequired should be less than 2");
                break;
            }
        }

        // If we didn't find it, try a different approach
        if (foundSlot == type(uint256).max) {
            // Maybe numConfirmationsRequired is at a specific known slot
            // Try slot 2 (after name and symbol in WBNB)
            bytes32 slot2Value = vm.load(TARGET, bytes32(uint256(2)));
            uint256 value2 = uint256(slot2Value);

            // Overwrite regardless of current value
            vm.store(TARGET, bytes32(uint256(2)), bytes32(uint256(1)));

            // Verify
            bytes32 newValue2 = vm.load(TARGET, bytes32(uint256(2)));
            assertLt(uint256(newValue2), 2, "numConfirmationsRequired at slot 2 should be less than 2");
        }
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

